const A=window.RachnaAPI,$=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
let page='home',projectId=null,quoteId=null,projectTab='overview',query='';
const nav=[['home','⌂','Home'],['inquiries','◌','Inquiries'],['projects','▦','Projects'],['customers','♙','Customers'],['vendors','◇','Vendors'],['team','♢','Team'],['tasks','☑','Tasks'],['money','₨','Money'],['quotations','▤','Quotations'],['services','✦','Services'],['marketing','◍','Marketing'],['reports','▥','Reports'],['settings','⚙','Settings']];
const BS_MONTHS=['Baisakh','Jestha','Ashadh','Shrawan','Bhadra','Ashwin','Kartik','Mangsir','Poush','Magh','Falgun','Chaitra'];
const esc=A.esc,money=A.money;
function toast(msg,error=false){const t=$('#toast');t.textContent=msg;t.className='toast show '+(error?'error':'');clearTimeout(window.__toast);window.__toast=setTimeout(()=>t.className='toast',3000)}
function closeModal(){$('#backdrop').classList.remove('show')}
function modal(title,body,actions){$('#modal').innerHTML='<div class="modal-head"><h2>'+title+'</h2><button class="close-btn" onclick="closeModal()">×</button></div><div class="modal-body">'+body+'</div><div class="modal-foot"><button class="btn" onclick="closeModal()">Cancel</button>'+actions+'</div>';$('#backdrop').classList.add('show')}
function field(label,id,type='text',value='',extra=''){return '<div class="field"><label>'+label+'</label><input id="'+id+'" type="'+type+'" value="'+esc(value)+'" '+extra+'></div>'}
function textarea(label,id,value=''){return '<div class="field full"><label>'+label+'</label><textarea id="'+id+'">'+esc(value)+'</textarea></div>'}
function selectField(label,id,opts,value=''){return '<div class="field"><label>'+label+'</label><select id="'+id+'">'+opts.map(o=>{const v=Array.isArray(o)?o[0]:o,l=Array.isArray(o)?o[1]:o;return '<option value="'+esc(v)+'" '+(String(v)===String(value)?'selected':'')+'>'+esc(l)+'</option>'}).join('')+'</select></div>'}
function bsToAd(v){try{return v&&window.DateConverter?new window.DateConverter(v).toAd():null}catch{return null}}
function adToBs(v){try{return v&&window.DateConverter?new window.DateConverter(v).toBs():null}catch{return null}}
function isoFromBs(v){const a=bsToAd(v||'');return a?String(a.year).padStart(4,'0')+'-'+String(a.month).padStart(2,'0')+'-'+String(a.date).padStart(2,'0'):null}
function isoDisplay(v){if(!v)return '—';const d=new Date(v+'T00:00:00');return isNaN(d)?v:d.toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'})}
function bsParts(value){if(/^\d{4}-\d{2}-\d{2}$/.test(value||'')){const p=value.split('-').map(Number);return {y:p[0],m:p[1],d:p[2]}}const now=adToBs(new Date().toISOString().slice(0,10));return {y:now?.year||2083,m:now?.month||8,d:now?.date||1}}
function validBsDays(y,m){const out=[];for(let d=1;d<=32;d++){const s=y+'-'+String(m).padStart(2,'0')+'-'+String(d).padStart(2,'0');const a=bsToAd(s);if(a)out.push(d)}return out.length?out:[1]}
function bsField(label,key,value=''){
  const p=bsParts(value),years=[];for(let y=2075;y<=2095;y++)years.push(y);
  const days=validBsDays(p.y,p.m),safeDay=days.includes(p.d)?p.d:days[days.length-1];
  const opts=(arr,fn,val)=>arr.map(x=>fn(x,val)).join('');
  return '<div class="field bs-field"><label>'+label+' (BS)</label><div class="bs-row"><select id="'+key+'_y" onchange="syncBS(\''+key+'\')">'+opts(years,(x,v)=>'<option value="'+x+'" '+(x===v?'selected':'')+'>'+x+'</option>',p.y)+'</select><select id="'+key+'_m" onchange="syncBS(\''+key+'\')">'+BS_MONTHS.map((n,i)=>'<option value="'+(i+1)+'" '+(i+1===p.m?'selected':'')+'>'+n+'</option>').join('')+'</select><select id="'+key+'_d" onchange="syncBS(\''+key+'\')">'+days.map(d=>'<option value="'+d+'" '+(d===safeDay?'selected':'')+'>'+d+'</option>').join('')+'</select></div><input type="hidden" id="'+key+'_v" value="'+esc(value)+'"><small class="muted" id="'+key+'_ad">'+(bsToAd(value)?'AD: '+isoDisplay(isoFromBs(value)):'Select BS date')+'</small></div>'
}
function syncBS(key){const y=Number($('#'+key+'_y').value),m=Number($('#'+key+'_m').value),d=Number($('#'+key+'_d').value),days=validBsDays(y,m);if(!days.includes(d)){const nd=days[days.length-1];$('#'+key+'_d').value=nd}const dd=Number($('#'+key+'_d').value),bs=y+'-'+String(m).padStart(2,'0')+'-'+String(dd).padStart(2,'0'),ad=bsToAd(bs);$('#'+key+'_v').value=bs;$('#'+key+'_ad').textContent=ad?'AD: '+isoDisplay(isoFromBs(bs)):'Invalid BS date'}
function tag(v){const s=String(v||'—');let c='gold';if(/booked|paid|done|completed|delivered|approved|active|won/i.test(s))c='green';else if(/new|pending|planning|negotiation|draft|awaiting|todo|in_progress|qualified/i.test(s))c='amber';return '<span class="tag '+c+'">'+esc(s.replaceAll('_',' '))+'</span>'}
function pageHead(k,title,sub,actions=''){return '<div class="page-head"><div><div class="eyebrow">'+esc(k)+'</div><h1>'+title+'</h1><div class="page-sub">'+sub+'</div></div><div class="action-row">'+actions+'</div></div>'}
function kpi(label,value,foot,icon='◆'){return '<div class="card kpi"><div class="kpi-top"><span>'+esc(label)+'</span><span class="kpi-icon">'+icon+'</span></div><div class="kpi-value">'+value+'</div><div class="kpi-foot">'+esc(foot)+'</div></div>'}
function table(title,heads,rows,actions=''){return '<div class="card"><div class="section-title"><h2>'+title+'</h2>'+actions+'</div><div class="table-wrap"><table class="table"><thead><tr>'+heads.map(h=>'<th>'+h+'</th>').join('')+'</tr></thead><tbody>'+ (rows.join('')||'<tr><td colspan="'+heads.length+'" class="empty">No records yet.</td></tr>')+'</tbody></table></div></div>'}
function save(fn,msg='Saved'){fn().then(()=>{closeModal();render();toast(msg)}).catch(e=>{console.error(e);toast(e.message||'Save failed',true)})}
async function navTo(p){page=p;projectId=null;quoteId=null;render()}
function refreshNow(){A.refresh().then(()=>{render();toast('Live data refreshed')}).catch(e=>toast(e.message,true))}
$('#nav').innerHTML=nav.map(n=>'<button class="nav-item" data-page="'+n[0]+'" onclick="navTo(\''+n[0]+'\')"><span>'+n[1]+'</span><span>'+n[2]+'</span></button>').join('');$('#refresh').onclick=refreshNow;$('#authBtn').onclick=authModal;$('#backdrop').onclick=e=>{if(e.target.id==='backdrop')closeModal()};
function render(){
  $$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#crumb').textContent=projectId?'Project':quoteId?'Quotation':(nav.find(n=>n[0]===page)||nav[0])[2];$('#userName').textContent=A.state.profile?.full_name||A.state.user?.email||'Offline';$('#userRole').textContent=A.state.profile?.role||'Workspace';
  const v={home,inquiries,projects,customers,vendors,team,tasks,moneyPage,quotations,services,marketing,reports,settings}[page]||home;$('#page').innerHTML=projectId?projectView():quoteId?quoteView():v()
}
function home(){const s=A.state,quoted=s.projects.reduce((a,p)=>a+Number(p.quoted_total||0),0),cost=s.projects.reduce((a,p)=>a+Number(p.internal_cost||0),0),inCash=s.payments.filter(p=>p.direction==='in').reduce((a,p)=>a+Number(p.amount||0),0),out=s.payments.filter(p=>p.direction==='out').reduce((a,p)=>a+Number(p.amount||0),0),open=s.inquiries.filter(i=>!['booked','lost'].includes(i.status)).length,up=s.functions.filter(f=>f.event_date).slice().sort((a,b)=>a.event_date.localeCompare(b.event_date)).slice(0,6);return pageHead('Rachna Company OS','Good morning','Your complete Nepal event planning control room.','<button class="btn" onclick="newInquiry()">+ New Inquiry</button><button class="btn primary" onclick="newProject()">+ New Project</button>')+'<div class="grid five-col">'+kpi('Open inquiries',open,'Sales pipeline','◌')+kpi('Booked projects',s.projects.filter(p=>p.status==='booked').length,'30% advance confirmation','▦')+kpi('Customer received',money(inCash),'Recorded cash in','₨')+kpi('Cash out',money(out),'Vendor + expenses','↗')+kpi('Expected gross profit',money(quoted-cost),'Quoted less current cost','◆')+'</div><div style="height:16px"></div><div class="grid two-col"><div class="card"><div class="section-title"><h2>Upcoming functions</h2><button class="btn" onclick="navTo(\'projects\')">View projects</button></div>'+up.map(f=>'<div class="event-item"><div class="mini-avatar">'+esc((f.name||'E')[0])+'</div><div><strong>'+esc(f.name)+'</strong><div class="muted">'+esc(f.event_date_bs||f.event_date)+' · '+esc(f.venue||'Venue TBC')+'</div></div>'+tag((f.guest_count||0)+' guests')+'</div>').join('')||'<div class="empty">No scheduled functions.</div>'+'</div><div class="card"><div class="section-title"><h2>Sales pipeline</h2><button class="btn" onclick="navTo(\'inquiries\')">Open</button></div><div class="pipeline-mini">'+['new','contacted','qualified','quote_sent','negotiation','awaiting_advance','booked'].map(st=>'<div><strong>'+s.inquiries.filter(i=>i.status===st).length+'</strong><span>'+st.replaceAll('_',' ')+'</span></div>').join('')+'</div></div></div>'}
function inquiries(){const stages=['new','contacted','qualified','quote_sent','negotiation','awaiting_advance','booked','lost'];return pageHead('Sales pipeline','Inquiries','Capture and qualify every lead before booking.','<button class="btn primary" onclick="newInquiry()">+ New Inquiry</button>')+'<div class="pipeline">'+stages.map(st=>'<div class="pipe-col"><div class="pipe-head"><span>'+st.replaceAll('_',' ')+'</span><span class="pipe-count">'+A.state.inquiries.filter(i=>i.status===st).length+'</span></div>'+A.state.inquiries.filter(i=>i.status===st).map(i=>'<div class="lead-card"><div class="lead-name">'+esc(i.event_name||'Untitled')+'</div><div class="lead-sub">'+esc(A.state.customers.find(c=>c.id===i.customer_id)?.name||'')+' · '+esc(i.event_date_bs||'Date TBC')+'<br>'+esc(i.venue||'Venue TBC')+' · '+money(i.budget)+'</div>'+tag(st)+'<div class="lead-foot"><button class="btn" onclick="openInquiry(\''+i.id+'\')">Open</button>'+(!['booked','lost'].includes(st)?'<button class="btn" onclick="stageNext(\''+i.id+'\',\''+st+'\')">Next →</button>':'')+'</div></div>').join('')||'<div class="empty">—</div>'+'</div>').join('')+'</div>'}
function projects(){const rows=A.state.projects.filter(p=>!query||String(p.name).toLowerCase().includes(query.toLowerCase())).map(p=>{const c=A.state.customers.find(x=>x.id===p.customer_id);return '<tr><td><strong>'+esc(p.name)+'</strong><br><small>'+esc(p.date_range_bs||'')+'</small></td><td>'+esc(c?.name||'—')+'</td><td>'+esc(p.brand||'—')+'</td><td>'+money(p.quoted_total)+'</td><td>'+money(p.customer_advance)+'</td><td>'+money(p.vendor_reserve)+'</td><td>'+tag(p.status)+'</td><td><button class="btn" onclick="openProject(\''+p.id+'\')">Open</button></td></tr>'});return pageHead('Production','Projects','One master project can contain unlimited functions, services, vendors, team, money and delivery.','<input class="search" placeholder="Search project" value="'+esc(query)+'" oninput="query=this.value;render()"><button class="btn primary" onclick="newProject()">+ New Project</button>')+table('Project register',['Project','Customer','Brand','Sale','Advance','Vendor reserve','Status',''],rows)}
function projectView(){const p=A.state.projects.find(x=>x.id===projectId);if(!p){projectId=null;return projects()}const c=A.state.customers.find(x=>x.id===p.customer_id),fs=A.state.functions.filter(x=>x.project_id===p.id),ps=A.state.projectServices.filter(x=>x.project_id===p.id),vb=A.state.vendorBookings.filter(x=>x.project_id===p.id),pt=A.state.projectTeam.filter(x=>x.project_id===p.id),ts=A.state.tasks.filter(x=>x.project_id===p.id),pay=A.state.payments.filter(x=>x.project_id===p.id),exp=A.state.expenses.filter(x=>x.project_id===p.id),pc=A.state.productionCosts.filter(x=>x.project_id===p.id),ds=A.state.deliverables.filter(x=>x.project_id===p.id),docs=A.state.documents.filter(x=>x.project_id===p.id),qs=A.state.quotations.filter(x=>x.project_id===p.id),profit=Number(p.quoted_total||0)-Number(p.internal_cost||0);let tabs=[['overview','Overview'],['schedule','Schedule'],['services','Services'],['commercial','Quotations'],['vendors','Vendors'],['team','Team'],['tasks','Tasks'],['money','Money'],['delivery','Delivery'],['documents','Documents']];let body=projectTab==='overview'?projectOverview(p,fs,ts,vb,ds):projectTab==='schedule'?schedule(fs):projectTab==='services'?projectServices(p,ps):projectTab==='commercial'?commercial(p,qs):projectTab==='vendors'?projectVendors(p,vb):projectTab==='team'?projectTeam(p,pt):projectTab==='tasks'?projectTasks(p,ts):projectTab==='money'?projectMoney(p,pay,exp,pc):projectTab==='delivery'?projectDelivery(p,ds):documents(p,docs);return pageHead('Project',esc(p.name),esc(c?.name||'Customer')+' · '+esc(p.brand||'Rachna'),'<button class="btn" onclick="backProjects()">Back</button><button class="btn" onclick="recordAdvance(\''+p.id+'\')">Advance</button><button class="btn primary" onclick="printProject(\''+p.id+'\')">Print</button>')+'<div class="grid five-col">'+kpi('Quoted',money(p.quoted_total),'Customer price')+kpi('Internal cost',money(p.internal_cost),'Current operational cost')+kpi('Gross profit',money(profit),'Before overhead')+kpi('Received',money(p.customer_advance),'Customer cash')+kpi('Due',money(Math.max(0,Number(p.quoted_total)-Number(p.customer_advance))),'Customer balance')+'</div><div class="subnav">'+tabs.map(t=>'<button class="subnav-btn '+(projectTab===t[0]?'active':'')+'" onclick="projectTab=\''+t[0]+'\';render()">'+t[1]+'</button>').join('')+'</div>'+body}
function projectOverview(p,fs,ts,vb,ds){return '<div class="grid two-col"><div class="card"><div class="section-title"><h2>Functions</h2><button class="btn" onclick="addFunction(\''+p.id+'\')">+ Function</button></div>'+fs.map(f=>'<div class="event-item"><div><strong>'+esc(f.name)+'</strong><div class="muted">'+esc(f.event_date_bs||f.event_date||'TBC')+' · '+esc(f.start_time||'Time TBC')+' · '+esc(f.venue||'Venue TBC')+'</div></div>'+tag((f.guest_count||0)+' guests')+'<button class="btn" onclick="editFunction(\''+f.id+'\')">Edit</button></div>').join('')||'<div class="empty">Add Mehendi, Haldi, Wedding, Reception or other functions.</div>'+'</div><div class="card"><div class="section-title"><h2>Attention</h2></div>'+ts.filter(t=>t.status!=='done').slice(0,6).map(t=>'<div class="sum-row"><span><strong>'+esc(t.title)+'</strong><br><small>'+esc(t.due_date||'No due date')+'</small></span>'+tag(t.status)+'<button class="btn" onclick="finishTask(\''+t.id+'\')">Done</button></div>').join('')||'<div class="empty">No open tasks.</div>'+'<div class="section-title" style="margin-top:18px"><h2>Vendor commitments</h2></div>'+vb.slice(0,5).map(v=>{const ven=A.state.vendors.find(x=>x.id===v.vendor_id);return '<div class="sum-row"><span>'+esc(ven?.name||'Vendor')+'</span><strong>'+money(v.quoted_cost)+'</strong></div>'}).join('')+'<div class="section-title" style="margin-top:18px"><h2>Aavartan delivery</h2></div>'+ds.slice(0,5).map(d=>'<div class="sum-row"><span>'+esc(d.deliverable)+'</span>'+tag(d.status)+'</div>').join('')+'</div></div>'}
function schedule(fs){return '<div class="card"><div class="section-title"><h2>Master schedule</h2><button class="btn" onclick="addFunction(\''+projectId+'\')">+ Function</button></div>'+fs.slice().sort((a,b)=>String(a.event_date||'9999').localeCompare(String(b.event_date||'9999'))).map(f=>'<div class="schedule-row"><div class="schedule-day">'+esc(f.event_date_bs||f.event_date||'TBC')+'</div><div><strong>'+esc(f.name)+'</strong><div class="muted">'+esc(f.start_time||'')+' · '+esc(f.venue||'Venue TBC')+' · '+esc(f.guest_count||'—')+' guests</div></div><button class="btn" onclick="editFunction(\''+f.id+'\')">Edit</button></div>').join('')||'<div class="empty">No functions.</div>'+'</div>'}
function projectServices(p,items){return '<div class="card"><div class="section-title"><h2>Project services</h2><button class="btn primary" onclick="addProjectService(\''+p.id+'\')">+ Add service</button></div>'+items.map(i=>{const f=A.state.functions.find(x=>x.id===i.function_id);return '<div class="sum-row"><span><strong>'+esc(i.name)+'</strong><br><small>'+esc(f?.name||'Project level')+' · Qty '+esc(i.quantity)+'</small></span><span>'+money(Number(i.customer_price)*Number(i.quantity))+'</span><strong>'+money(Number(i.internal_cost)*Number(i.quantity))+'</strong><button class="btn" onclick="editProjectService(\''+i.id+'\')">Edit</button></div>'}).join('')||'<div class="empty">Add services from the catalog to build the project scope.</div>'+'</div>'}
function commercial(p,qs){return '<div class="card"><div class="section-title"><h2>Quotations</h2><button class="btn primary" onclick="newQuote(\''+p.id+'\')">+ New version</button></div>'+qs.map(q=>'<div class="sum-row"><span><strong>Version '+q.version+'</strong><br><small>'+esc(q.status)+'</small></span><span>'+money(q.customer_total)+'</span><button class="btn" onclick="openQuote(\''+q.id+'\')">Open</button></div>').join('')||'<div class="empty">No quotation yet.</div>'+'</div>'}
function projectVendors(p,items){return '<div class="card"><div class="section-title"><h2>Vendor bookings</h2><button class="btn primary" onclick="bookVendor(\''+p.id+'\')">+ Book vendor</button></div>'+items.map(v=>{const ven=A.state.vendors.find(x=>x.id===v.vendor_id),fn=A.state.functions.find(x=>x.id===v.function_id);return '<div class="sum-row"><span><strong>'+esc(ven?.name||'Vendor')+'</strong><br><small>'+esc(fn?.name||'Project')+' · '+esc(v.status)+'</small></span><span>'+money(v.advance_paid)+' / '+money(v.final_paid)+'</span><strong>'+money(v.quoted_cost)+'</strong><button class="btn" onclick="payVendor(\''+v.id+'\')">Pay</button></div>'}).join('')||'<div class="empty">No vendor booking yet.</div>'+'</div>'}
function projectTeam(p,items){return '<div class="card"><div class="section-title"><h2>Assigned team</h2><button class="btn primary" onclick="assignTeam(\''+p.id+'\')">+ Assign</button></div>'+items.map(x=>{const t=A.state.team.find(z=>z.id===x.team_member_id),f=A.state.functions.find(z=>z.id===x.function_id);return '<div class="sum-row"><span><strong>'+esc(t?.name||'Team member')+'</strong><br><small>'+esc(t?.role||'')+' · '+esc(x.responsibility||'')+' · '+esc(f?.name||'Project')+'</small></span><strong>'+money(x.rate)+'</strong></div>'}).join('')||'<div class="empty">Assign coordinators, photographers, videographers or production staff.</div>'+'</div>'}
function projectTasks(p,items){return '<div class="card"><div class="section-title"><h2>Tasks</h2><button class="btn primary" onclick="newTask(\''+p.id+'\')">+ Task</button></div>'+items.map(t=>'<div class="sum-row"><span><strong>'+esc(t.title)+'</strong><br><small>'+esc(t.due_date||'No due date')+' · '+esc(A.state.team.find(m=>m.id===t.assignee_id)?.name||'Unassigned')+'</small></span>'+tag(t.status)+'<button class="btn" onclick="editTask(\''+t.id+'\')">Edit</button>'+ (t.status!=='done'?'<button class="btn" onclick="finishTask(\''+t.id+'\')">Done</button>':'')+'</div>').join('')||'<div class="empty">No tasks.</div>'+'</div>'}
function projectMoney(p,pay,exp,pc){const ins=pay.filter(x=>x.direction==='in').reduce((a,x)=>a+Number(x.amount||0),0),out=pay.filter(x=>x.direction==='out').reduce((a,x)=>a+Number(x.amount||0),0),e=exp.reduce((a,x)=>a+Number(x.amount||0),0);return '<div class="grid two-col"><div class="card"><div class="section-title"><h2>Payments</h2><button class="btn primary" onclick="newPayment(\''+p.id+'\')">+ Payment</button></div>'+pay.map(x=>'<div class="sum-row"><span>'+esc(x.party_type)+'<br><small>'+esc(x.payment_date)+' · '+esc(x.method||'')+'</small></span><strong>'+ (x.direction==='in'?'+':'-')+money(x.amount)+'</strong></div>').join('')||'<div class="empty">No payments.</div>'+'</div><div class="card"><div class="section-title"><h2>Expenses & production</h2><button class="btn" onclick="newExpense(\''+p.id+'\')">+ Expense</button><button class="btn" onclick="newProduction(\''+p.id+'\')">+ Cost</button></div><div class="profit"><div><span>Customer cash</span><b>'+money(ins)+'</b></div><div><span>Payments out</span><b>'+money(out)+'</b></div><div><span>Expenses</span><b>'+money(e)+'</b></div></div>'+exp.map(x=>'<div class="sum-row"><span>'+esc(x.category)+' · '+esc(x.description)+'</span><strong>'+money(x.amount)+'</strong></div>').join('')+pc.map(x=>'<div class="sum-row"><span>'+esc(x.brand)+' · '+esc(x.description)+'</span><strong>'+money(Number(x.quantity)*Number(x.unit_cost))+'</strong></div>').join('')+'</div></div>'}
function projectDelivery(p,items){return '<div class="card"><div class="section-title"><h2>Aavartan delivery</h2><button class="btn primary" onclick="newDeliverable(\''+p.id+'\')">+ Deliverable</button></div><div class="delivery-grid">'+items.map(d=>'<div class="delivery"><strong>'+esc(d.deliverable)+'</strong>'+tag(d.status)+'<small>'+esc(d.due_date||'No due date')+'</small><button class="btn" onclick="cycleDelivery(\''+d.id+'\',\''+d.status+'\')">Advance</button></div>').join('')||'<div class="empty">Track gallery, photo edit, video edit, highlight, full video, album, frame, pendrive and final delivery.</div>'+'</div></div>'}
function documents(p,items){return '<div class="card"><div class="section-title"><h2>Documents & links</h2><button class="btn primary" onclick="newDocument(\''+p.id+'\')">+ Document</button></div>'+items.map(d=>'<div class="sum-row"><span><strong>'+esc(d.title)+'</strong><br><small>'+esc(d.kind)+' · '+esc(d.url||'No URL')+'</small></span>'+tag(d.status)+(d.url?'<a class="btn" target="_blank" rel="noopener" href="'+esc(d.url)+'">Open</a>':'')+'</div>').join('')||'<div class="empty">Store quotation, contract, Drive, moodboard or venue links.</div>'+'</div>'}
function customers(){return pageHead('People','Customers','Central customer records linked to inquiries and projects.','<button class="btn primary" onclick="newCustomer()">+ Customer</button>')+table('Customers',['Customer','Phone','WhatsApp','Projects',''],A.state.customers.map(c=>'<tr><td><strong>'+esc(c.name)+'</strong></td><td>'+esc(c.phone||'')+'</td><td>'+esc(c.whatsapp||'')+'</td><td>'+A.state.projects.filter(p=>p.customer_id===c.id).length+'</td><td><button class="btn" onclick="editCustomer(\''+c.id+'\')">Edit</button></td></tr>'))}
function vendors(){return pageHead('Network','Vendors','Decoration, catering, entertainment and other supplier network.','<button class="btn primary" onclick="newVendor()">+ Vendor</button>')+table('Vendor book',['Vendor','Category','Area','Reliability','Rate guide',''],A.state.vendors.map(v=>'<tr><td><strong>'+esc(v.name)+'</strong></td><td>'+esc(v.service_category||'')+'</td><td>'+esc(v.area||'')+'</td><td>'+tag(v.reliability)+'</td><td>'+esc(v.rate_guide||'')+'</td><td><button class="btn" onclick="editVendor(\''+v.id+'\')">Edit</button></td></tr>'))}
function team(){return pageHead('People','Team','Internal staff and production resources.','<button class="btn primary" onclick="newTeam()">+ Team member</button>')+table('Team',['Name','Role','Phone','Email','Status',''],A.state.team.map(t=>'<tr><td><strong>'+esc(t.name)+'</strong></td><td>'+esc(t.role||'')+'</td><td>'+esc(t.phone||'')+'</td><td>'+esc(t.email||'')+'</td><td>'+tag(t.active?'active':'inactive')+'</td><td><button class="btn" onclick="editTeam(\''+t.id+'\')">Edit</button></td></tr>'))}
function tasks(){return pageHead('Work','Tasks','All operational tasks across projects and functions.','<button class="btn primary" onclick="newTask()">+ Task</button>')+table('Task board',['Task','Project','Due','Assignee','Status',''],A.state.tasks.map(t=>'<tr><td><strong>'+esc(t.title)+'</strong></td><td>'+esc(A.state.projects.find(p=>p.id===t.project_id)?.name||'')+'</td><td>'+esc(t.due_date||'')+'</td><td>'+esc(A.state.team.find(m=>m.id===t.assignee_id)?.name||'Unassigned')+'</td><td>'+tag(t.status)+'</td><td><button class="btn" onclick="editTask(\''+t.id+'\')">Edit</button></td></tr>'))}
function moneyPage(){const s=A.state,ins=s.payments.filter(p=>p.direction==='in').reduce((a,p)=>a+Number(p.amount||0),0),out=s.payments.filter(p=>p.direction==='out').reduce((a,p)=>a+Number(p.amount||0),0),exp=s.expenses.reduce((a,p)=>a+Number(p.amount||0),0);return pageHead('Finance','Money','Customer receipts, vendor/team payments and project expenses.','<button class="btn" onclick="newPayment()">+ Payment</button><button class="btn primary" onclick="newExpense()">+ Expense</button>')+'<div class="grid four-col">'+kpi('Received',money(ins),'Customer cash','↙')+kpi('Paid out',money(out),'Vendor / team','↗')+kpi('Expenses',money(exp),'Project / shared','◆')+kpi('Net cash',money(ins-out-exp),'Recorded cash','₨')+'</div><div style="height:16px"></div>'+table('Payments',['Date','Project','Direction','Party','Amount','Method'],s.payments.map(p=>'<tr><td>'+isoDisplay(p.payment_date)+'</td><td>'+esc(s.projects.find(x=>x.id===p.project_id)?.name||'')+'</td><td>'+tag(p.direction)+'</td><td>'+esc(p.party_type)+'</td><td>'+money(p.amount)+'</td><td>'+esc(p.method||'')+'</td></tr>'))}
function quotations(){return pageHead('Sales','Quotations','Customer proposals with versions, line items and protected internal cost.','<button class="btn primary" onclick="navTo(\'projects\')">Open projects</button>')+table('Quotation register',['Version','Project','Status','Customer total','Internal cost',''],A.state.quotations.map(q=>'<tr><td>v'+q.version+'</td><td>'+esc(A.state.projects.find(p=>p.id===q.project_id)?.name||'')+'</td><td>'+tag(q.status)+'</td><td>'+money(q.customer_total)+'</td><td>'+money(q.internal_total)+'</td><td><button class="btn" onclick="openQuote(\''+q.id+'\')">Open</button></td></tr>'))}
function quoteView(){const q=A.state.quotations.find(x=>x.id===quoteId),p=A.state.projects.find(x=>x.id===q?.project_id);if(!q||!p){quoteId=null;return quotations()}const items=A.state.quotationItems.filter(i=>i.quotation_id===q.id),profit=Number(q.customer_total||0)-Number(q.internal_total||0);return pageHead('Quotation','Version '+q.version+' · '+esc(p.name),'Customer pricing and internal cost come from line items.','<button class="btn" onclick="closeQuoteView()">Back</button><button class="btn" onclick="addQuoteVersion(\''+p.id+'\',\''+q.id+'\')">Copy as new version</button><button class="btn primary" onclick="printQuote(\''+q.id+'\')">Print / PDF</button>')+'<div class="grid four-col">'+kpi('Customer total',money(q.customer_total),'Client price')+kpi('Internal cost',money(q.internal_total),'Protected cost')+kpi('Gross profit',money(profit),'Before overhead')+kpi('Margin',(Number(q.customer_total)?((profit/Number(q.customer_total))*100).toFixed(1):'0')+'%','Gross margin')+'</div><div style="height:16px"></div>'+table('Line items',['Description','Function','Qty','Customer','Internal',''],items.map(i=>'<tr><td><strong>'+esc(i.description)+'</strong></td><td>'+esc(A.state.functions.find(f=>f.id===i.function_id)?.name||'Project')+'</td><td>'+esc(i.quantity)+'</td><td>'+money(Number(i.customer_price)*Number(i.quantity))+'</td><td>'+money(Number(i.internal_cost)*Number(i.quantity))+'</td><td><button class="btn" onclick="editQuoteItem(\''+i.id+'\')">Edit</button></td></tr>'),'<button class="btn primary" onclick="newQuoteItem(\''+q.id+'\')">+ Line item</button><select class="mini-select" onchange="updateQuoteStatus(\''+q.id+'\',this.value)"><option value="draft" '+(q.status==='draft'?'selected':'')+'>Draft</option><option value="sent" '+(q.status==='sent'?'selected':'')+'>Sent</option><option value="approved" '+(q.status==='approved'?'selected':'')+'>Approved</option><option value="rejected" '+(q.status==='rejected'?'selected':'')+'>Rejected</option></select>')}
function services(){return pageHead('Catalog','Services & Packages','Rachna planning/decoration plus Aavartan visual services and deliverables.','<button class="btn primary" onclick="newService()">+ Service</button>')+table('Service catalog',['Brand','Service','Category','Customer base','Internal cost','Status',''],A.state.services.map(s=>'<tr><td>'+esc(s.brand)+'</td><td><strong>'+esc(s.name)+'</strong></td><td>'+esc(s.category||'')+'</td><td>'+money(s.base_price)+'</td><td>'+money(s.internal_cost)+'</td><td>'+tag(s.active?'active':'inactive')+'</td><td><button class="btn" onclick="editService(\''+s.id+'\')">Edit</button></td></tr>'))}
function marketing(){const m=A.state.marketing,sp=m.reduce((a,x)=>a+Number(x.spend||0),0);return pageHead('Growth','Marketing','Campaign, channel, content, spend and lead status.','<button class="btn primary" onclick="newMarketing()">+ Campaign lead</button>')+'<div class="grid four-col">'+kpi('Leads',m.length,'Recorded')+kpi('Spend',money(sp),'Tracked spend')+kpi('Won',m.filter(x=>x.lead_status==='won').length,'Converted')+kpi('CPL',money(m.length?sp/m.length:0),'Cost per lead')+'</div><div style="height:16px"></div>'+table('Marketing leads',['Campaign','Channel','Content','Spend','Status',''],m.map(x=>'<tr><td>'+esc(x.campaign||'')+'</td><td>'+esc(x.channel||'')+'</td><td>'+esc(x.content||'')+'</td><td>'+money(x.spend)+'</td><td>'+tag(x.lead_status)+'</td><td><button class="btn" onclick="editMarketing(\''+x.id+'\')">Edit</button></td></tr>'))}
function reports(){const s=A.state,quoted=s.projects.reduce((a,p)=>a+Number(p.quoted_total||0),0),cost=s.projects.reduce((a,p)=>a+Number(p.internal_cost||0),0),book=s.projects.filter(p=>p.status==='booked').length,total=s.inquiries.length,bookedIn=s.inquiries.filter(i=>i.status==='booked').length,vendorDue=s.vendorBookings.reduce((a,v)=>a+Math.max(0,Number(v.quoted_cost)-Number(v.advance_paid||0)-Number(v.final_paid||0)),0),custDue=s.projects.reduce((a,p)=>a+Math.max(0,Number(p.quoted_total)-Number(p.customer_advance||0)),0);return pageHead('Management','Reports','Pipeline, sales, profit and outstanding commitments.','<button class="btn" onclick="printReport()">Print report</button>')+'<div class="grid four-col">'+kpi('Projects',s.projects.length,'All records')+kpi('Booked',book,'Confirmed')+kpi('Quoted sales',money(quoted),'Customer value')+kpi('Expected profit',money(quoted-cost),'Before overhead')+'</div><div style="height:16px"></div><div class="grid two-col"><div class="card"><h2>Conversion</h2><div class="profit"><div><span>Total inquiries</span><b>'+total+'</b></div><div><span>Booked inquiries</span><b>'+bookedIn+'</b></div><div><span>Booking conversion</span><b>'+ (total?((bookedIn/total)*100).toFixed(1):'0')+'%</b></div></div></div><div class="card"><h2>Outstanding</h2><div class="profit"><div><span>Vendor balance</span><b>'+money(vendorDue)+'</b></div><div><span>Customer due</span><b>'+money(custDue)+'</b></div><div><span>Open tasks</span><b>'+s.tasks.filter(t=>t.status!=='done').length+'</b></div></div></div></div>'}
function settings(){return pageHead('Workspace','Settings','Authentication, workspace identity and business rules.','<button class="btn primary" onclick="authModal()">'+(A.state.user?'Account':'Sign in')+'</button>')+'<div class="grid two-col"><div class="card"><h2>Workspace</h2><p><strong>'+esc(A.state.org?.name||'Not connected')+'</strong></p><p class="muted">'+esc(A.state.profile?.full_name||A.state.user?.email||'Not signed in')+' · '+esc(A.state.profile?.role||'')+'</p></div><div class="card"><h2>Operating rules</h2><div class="rule-row"><span>Customer advance to confirm</span><strong>30%</strong></div><div class="rule-row"><span>Vendor reserve</span><strong>15% of received advance</strong></div><div class="rule-row"><span>Currency</span><strong>NPR</strong></div><div class="rule-row"><span>Master project</span><strong>Unlimited functions</strong></div></div></div>'}
function newCustomer(){modal('New customer','<div class="form-grid">'+field('Name','cn')+field('Phone','cp')+field('WhatsApp','cw')+field('Email','ce','email')+textarea('Notes','cno')+'</div>','<button class="btn primary" onclick="save(()=>A.createCustomer({name:$(\'#cn\').value,phone:$(\'#cp\').value,whatsapp:$(\'#cw\').value,email:$(\'#ce\').value,notes:$(\'#cno\').value}),\'Customer created\')">Create</button>')}
function editCustomer(id){const c=A.state.customers.find(x=>x.id===id);modal('Edit customer','<div class="form-grid">'+field('Name','cn','text',c.name)+field('Phone','cp','text',c.phone||'')+field('WhatsApp','cw','text',c.whatsapp||'')+field('Email','ce','email',c.email||'')+textarea('Notes','cno',c.notes||'')+'</div>','<button class="btn primary" onclick="save(()=>A.update(\'customers\',\''+id+'\',{name:$(\'#cn\').value,phone:$(\'#cp\').value,whatsapp:$(\'#cw\').value,email:$(\'#ce\').value,notes:$(\'#cno\').value}),\'Customer updated\')">Save</button>')}
function newInquiry(){modal('New inquiry','<div class="form-grid">'+field('Event / project','en')+field('Customer name','ecn')+field('Phone / WhatsApp','ep')+selectField('Source','es',['Instagram','Facebook','WhatsApp','Referral','Phone','Website','Other'])+bsField('Event date','ebs')+field('Venue','ev')+field('Guests','eg','number')+field('Budget (optional)','ebudget','number')+field('Needs','eneed')+textarea('Notes','eno')+'</div>','<button class="btn primary" onclick="save(()=>A.createInquiry({event_name:$(\'#en\').value,customer_name:$(\'#ecn\').value,phone:$(\'#ep\').value,whatsapp:$(\'#ep\').value,source:$(\'#es\').value,event_date_bs:$(\'#ebs_v\').value,venue:$(\'#ev\').value,guest_count:Number($(\'#eg\').value)||null,budget:Number($(\'#ebudget\').value)||null,notes:($(\'#eneed\').value?\'Need: \'+$(\'#eneed\').value+\'\\n\':\'\')+$(\'#eno\').value}),\'Inquiry created\')">Create</button>')}
function openInquiry(id){const i=A.state.inquiries.find(x=>x.id===id),c=A.state.customers.find(x=>x.id===i.customer_id),existing=A.state.projects.find(p=>p.inquiry_id===id);modal('Inquiry','<div class="detail-grid"><div><label>Customer</label><strong>'+esc(c?.name||'')+'</strong></div><div><label>Status</label>'+tag(i.status)+'</div><div><label>Event</label><strong>'+esc(i.event_name||'')+'</strong></div><div><label>BS date</label><strong>'+esc(i.event_date_bs||'TBC')+'</strong></div><div><label>Phone</label><strong>'+esc(c?.phone||'')+'</strong></div><div><label>Venue</label><strong>'+esc(i.venue||'TBC')+'</strong></div><div><label>Guests</label><strong>'+esc(i.guest_count||'')+'</strong></div><div><label>Budget</label><strong>'+money(i.budget)+'</strong></div></div><p class="muted">'+esc(i.notes||'No notes')+'</p>',''+(existing?'<button class="btn primary" onclick="closeModal();openProject(\''+existing.id+'\')">Open project</button>':'<button class="btn primary" onclick="save(async()=>{const p=await A.convertInquiry(\''+id+'\');projectId=p.id},\'Project created\')">Convert to project</button>')+'<button class="btn" onclick="editInquiry(\''+id+'\')">Edit</button><select class="mini-select" onchange="updateInquiryStatus(\''+id+'\',this.value)"><option>new</option><option>contacted</option><option>qualified</option><option>quote_sent</option><option>negotiation</option><option>awaiting_advance</option><option>booked</option><option>lost</option></select>')}
function editInquiry(id){const i=A.state.inquiries.find(x=>x.id===id);modal('Edit inquiry','<div class="form-grid">'+field('Event','en','text',i.event_name||'')+bsField('Event date','ebs',i.event_date_bs||'')+field('Venue','ev','text',i.venue||'')+field('Guests','eg','number',i.guest_count||'')+field('Budget','ebudget','number',i.budget||'')+textarea('Notes','eno',i.notes||'')+'</div>','<button class="btn primary" onclick="save(()=>A.update(\'inquiries\',\''+id+'\',{event_name:$(\'#en\').value,event_date_bs:$(\'#ebs_v\').value,venue:$(\'#ev\').value,guest_count:Number($(\'#eg\').value)||null,budget:Number($(\'#ebudget\').value)||null,notes:$(\'#eno\').value,updated_at:new Date().toISOString()}),\'Inquiry updated\')">Save</button>')}
function updateInquiryStatus(id,status){save(()=>A.update('inquiries',id,{status,updated_at:new Date().toISOString()}),'Pipeline updated')}
function stageNext(id,st){const a=['new','contacted','qualified','quote_sent','negotiation','awaiting_advance','booked'];updateInquiryStatus(id,a[Math.min(a.length-1,Math.max(0,a.indexOf(st)+1))])}
function newProject(){modal('New project','<div class="form-grid">'+field('Project name','pn')+selectField('Customer','pc',[['','Select customer'],...A.state.customers.map(c=>[c.id,c.name])])+selectField('Brand','pb',['Rachna + Aavartan','Rachna','Aavartan'])+bsField('First event date','pdate')+field('Date range note','prange','text','')+field('First function (optional)','pfn')+'</div>','<button class="btn primary" onclick="save(async()=>{const p=await A.insertProject({customer_id:$(\'#pc\').value||null,name:$(\'#pn\').value,brand:$(\'#pb\').value,date_range_bs:($(\'#prange\').value||$(\'#pdate_v\').value||null),function_name:$(\'#pfn\').value,event_date:isoFromBs($(\'#pdate_v\').value),event_date_bs:$(\'#pdate_v\').value});projectId=p.id},\'Project created\')">Create</button>')}
function addFunction(pid){modal('Add function','<div class="form-grid">'+field('Function','fn')+bsField('Event date','fbs')+field('Start time','ft','time')+field('Venue','fv')+field('Guests','fg','number')+textarea('Notes','fno')+'</div>','<button class="btn primary" onclick="save(()=>A.addFunction(\''+pid+'\',{name:$(\'#fn\').value,event_date:isoFromBs($(\'#fbs_v\').value),event_date_bs:$(\'#fbs_v\').value,start_time:$(\'#ft\').value||null,venue:$(\'#fv\').value,guest_count:Number($(\'#fg\').value)||null,notes:$(\'#fno\').value}),\'Function added\')">Add</button>')}
function editFunction(id){const f=A.state.functions.find(x=>x.id===id);modal('Edit function','<div class="form-grid">'+field('Function','fn','text',f.name)+bsField('Event date','fbs',f.event_date_bs||'')+field('Start time','ft','time',String(f.start_time||'').slice(0,5))+field('Venue','fv','text',f.venue||'')+field('Guests','fg','number',f.guest_count||'')+textarea('Notes','fno',f.notes||'')+'</div>','<button class="btn primary" onclick="save(()=>A.update(\'event_functions\',\''+id+'\',{name:$(\'#fn\').value,event_date:isoFromBs($(\'#fbs_v\').value),event_date_bs:$(\'#fbs_v\').value,start_time:$(\'#ft\').value||null,venue:$(\'#fv\').value,guest_count:Number($(\'#fg\').value)||null,notes:$(\'#fno\').value}),\'Function updated\')">Save</button>')}
function recordAdvance(pid){modal('Customer advance','<div class="form-grid">'+field('Amount received','pa','number')+selectField('Method','pm',['Bank Transfer','Cash','eSewa / Khalti','Card','Other'])+field('Reference','pr')+'</div><p class="muted">Booking is confirmed when cumulative customer advance reaches 30% of the project quotation. Vendor reserve is 15% of received customer advance.</p>','<button class="btn primary" onclick="save(()=>A.recordAdvance(\''+pid+'\',Number($(\'#pa\').value),$(\'#pm\').value,$(\'#pr\').value).then(r=>toast(r.booked?\'Booking confirmed · Vendor reserve \'+money(r.reserve):\'Advance recorded\')),\'Advance recorded\')">Record</button>')}
function newVendor(){modal('New vendor','<div class="form-grid">'+field('Name','vn')+field('Phone','vp')+field('Category','vc')+field('Area','va')+field('Rate guide','vr')+selectField('Reliability','vrel',['High','Medium','Low'])+textarea('Notes','vno')+'</div>','<button class="btn primary" onclick="save(()=>A.addVendor({name:$(\'#vn\').value,phone:$(\'#vp\').value,category:$(\'#vc\').value,area:$(\'#va\').value,rate_guide:$(\'#vr\').value,reliability:$(\'#vrel\').value,notes:$(\'#vno\').value}),\'Vendor added\')">Create</button>')}
function editVendor(id){const v=A.state.vendors.find(x=>x.id===id);modal('Edit vendor','<div class="form-grid">'+field('Name','vn','text',v.name)+field('Phone','vp','text',v.phone||'')+field('Category','vc','text',v.service_category||'')+field('Area','va','text',v.area||'')+field('Rate guide','vr','text',v.rate_guide||'')+selectField('Reliability','vrel',['High','Medium','Low'],v.reliability)+textarea('Notes','vno',v.notes||'')+'</div>','<button class="btn primary" onclick="save(()=>A.update(\'vendors\',\''+id+'\',{name:$(\'#vn\').value,phone:$(\'#vp\').value,service_category:$(\'#vc\').value,area:$(\'#va\').value,rate_guide:$(\'#vr\').value,reliability:$(\'#vrel\').value,notes:$(\'#vno\').value}),\'Vendor updated\')">Save</button>')}
function bookVendor(pid){modal('Book vendor','<div class="form-grid">'+selectField('Vendor','bv',A.state.vendors.map(v=>[v.id,v.name+' · '+(v.service_category||'')]))+selectField('Function','bf',[['','Project level'],...A.state.functions.filter(f=>f.project_id===pid).map(f=>[f.id,f.name])])+field('Agreed vendor cost','bc','number')+'</div>','<button class="btn primary" onclick="save(()=>A.addVendorBooking({project_id:\''+pid+'\',function_id:$(\'#bf\').value||null,vendor_id:$(\'#bv\').value,quoted_cost:Number($(\'#bc\').value)||0,advance_paid:0,final_paid:0,status:\'reserved\'}),\'Vendor booking added\')">Book</button>')}
function payVendor(id){const v=A.state.vendorBookings.find(x=>x.id===id);modal('Vendor payment','<div class="form-grid">'+field('Amount','va','number')+selectField('Stage','vs',['advance','final'])+selectField('Method','vm',['Bank Transfer','Cash','eSewa / Khalti','Other'])+'</div>','<button class="btn primary" onclick="save(async()=>{const n=Number($(\'#va\').value)||0,stage=$(\'#vs\').value,field=stage===\'advance\'?\'advance_paid\':\'final_paid\';await A.updateVendorBooking(\''+id+'\',{[field]:Number(v[field]||0)+n,status:stage===\'final\'?\'completed\':\'reserved\'},v.project_id);await A.recordPayment({project_id:v.project_id,direction:\'out\',party_type:\'vendor\',party_id:v.vendor_id,amount:n,method:$(\'#vm\').value})},\'Vendor payment recorded\')">Record</button>')}
function newTeam(){modal('Team member','<div class="form-grid">'+field('Name','tn')+field('Role','tr')+field('Phone','tp')+field('Email','te','email')+'</div>','<button class="btn primary" onclick="save(()=>A.addTeam({name:$(\'#tn\').value,role:$(\'#tr\').value,phone:$(\'#tp\').value,email:$(\'#te\').value}),\'Team member added\')">Create</button>')}
function editTeam(id){const t=A.state.team.find(x=>x.id===id);modal('Edit team member','<div class="form-grid">'+field('Name','tn','text',t.name)+field('Role','tr','text',t.role||'')+field('Phone','tp','text',t.phone||'')+field('Email','te','email',t.email||'')+selectField('Status','ta',[['true','Active'],['false','Inactive']],String(t.active))+'</div>','<button class="btn primary" onclick="save(()=>A.update(\'team_members\',\''+id+'\',{name:$(\'#tn\').value,role:$(\'#tr\').value,phone:$(\'#tp\').value,email:$(\'#te\').value,active:$(\'#ta\').value===\'true\'}),\'Team member updated\')">Save</button>')}
function assignTeam(pid){modal('Assign team member','<div class="form-grid">'+selectField('Team member','tm',A.state.team.filter(t=>t.active).map(t=>[t.id,t.name+' · '+(t.role||'')]))+selectField('Function','tf',[['','Project level'],...A.state.functions.filter(f=>f.project_id===pid).map(f=>[f.id,f.name])])+field('Responsibility','trsp')+field('Rate','trate','number')+'</div>','<button class="btn primary" onclick="save(()=>A.assignTeam({project_id:\''+pid+'\',team_member_id:$(\'#tm\').value,function_id:$(\'#tf\').value||null,responsibility:$(\'#trsp\').value,rate:Number($(\'#trate\').value)||0}),\'Team assigned\')">Assign</button>')}
function newTask(pid=''){modal('Task','<div class="form-grid">'+selectField('Project','tpj',A.state.projects.map(p=>[p.id,p.name]),pid)+field('Task','tt')+selectField('Function','tf',[['','Project level'],...A.state.functions.filter(f=>f.project_id===pid).map(f=>[f.id,f.name])])+selectField('Assignee','ta',[['','Unassigned'],...A.state.team.filter(t=>t.active).map(t=>[t.id,t.name])])+field('Due date','td','date')+selectField('Status','ts',['todo','in_progress','done'])+'</div>','<button class="btn primary" onclick="save(()=>A.addTask({project_id:$(\'#tpj\').value,function_id:$(\'#tf\').value||null,title:$(\'#tt\').value,assignee_id:$(\'#ta\').value||null,due_date:$(\'#td\').value||null,status:$(\'#ts\').value}),\'Task created\')">Create</button>')}
function editTask(id){const t=A.state.tasks.find(x=>x.id===id);modal('Edit task','<div class="form-grid">'+field('Task','tt','text',t.title)+selectField('Assignee','ta',[['','Unassigned'],...A.state.team.map(x=>[x.id,x.name])],t.assignee_id||'')+field('Due date','td','date',t.due_date||'')+selectField('Status','ts',['todo','in_progress','done'],t.status)+'</div>','<button class="btn primary" onclick="save(()=>A.updateTask(\''+id+'\',{title:$(\'#tt\').value,assignee_id:$(\'#ta\').value||null,due_date:$(\'#td\').value||null,status:$(\'#ts\').value}),\'Task updated\')">Save</button>')}
