function newExpense(pid=''){modal('Expense','<div class="form-grid">'+selectField('Project','ep',[['','Business / shared'],...A.state.projects.map(p=>[p.id,p.name])],pid)+field('Category','ec')+field('Description','ed')+field('Amount','ea','number')+selectField('Method','em',['Bank Transfer','Cash','eSewa / Khalti','Other'])+field('Expense date','edate','date')+textarea('Notes','eno')+'</div>','<button class="btn primary" onclick="save(()=>A.recordExpense({project_id:$(\'#ep\').value||null,category:$(\'#ec\').value,description:$(\'#ed\').value,amount:Number($(\'#ea\').value)||0,method:$(\'#em\').value,expense_date:$(\'#edate\').value||undefined,notes:$(\'#eno\').value}),\'Expense added\')">Add</button>')}
function newProduction(pid){modal('Internal production cost','<div class="form-grid">'+selectField('Brand','pb',['Rachna','Aavartan'])+selectField('Category','pc',['Vendor','Manpower','Gadget Rental','Editing','Album','Frame','Pendrive','Transport','Other'])+field('Description','pdesc')+field('Quantity','pq','number','1')+field('Unit cost','pu','number')+selectField('Function','pf',[['','Project level'],...A.state.functions.filter(f=>f.project_id===pid).map(f=>[f.id,f.name])])+'</div>','<button class="btn primary" onclick="save(()=>A.addProductionCost({project_id:\''+pid+'\',brand:$(\'#pb\').value,category:$(\'#pc\').value,description:$(\'#pdesc\').value,quantity:Number($(\'#pq\').value)||1,unit_cost:Number($(\'#pu\').value)||0,function_id:$(\'#pf\').value||null}),\'Internal cost added\')">Add cost</button>')}
function addProjectService(pid){modal('Add project service','<div class="form-grid">'+selectField('Service','sid',A.state.services.filter(s=>s.active).map(s=>[s.id,s.brand+' · '+s.name]))+selectField('Function','sfn',[['','Project level'],...A.state.functions.filter(f=>f.project_id===pid).map(f=>[f.id,f.name])])+field('Customer price / unit','scp','number')+field('Internal cost / unit','sic','number')+field('Quantity','sq','number','1')+'</div>','<button class="btn primary" onclick="save(()=>{const s=A.state.services.find(x=>x.id===$(\'#sid\').value);return A.addProjectService({project_id:\''+pid+'\',service_id:s?.id||null,function_id:$(\'#sfn\').value||null,name:s?.name||\'Service\',customer_price:Number($(\'#scp\').value)||Number(s?.base_price||0),internal_cost:Number($(\'#sic\').value)||Number(s?.internal_cost||0),quantity:Number($(\'#sq\').value)||1})},\'Service added\')">Add</button>')}
function editProjectService(id){const i=A.state.projectServices.find(x=>x.id===id);modal('Edit project service','<div class="form-grid">'+field('Service name','sn','text',i.name)+field('Customer price / unit','scp','number',i.customer_price)+field('Internal cost / unit','sic','number',i.internal_cost)+field('Quantity','sq','number',i.quantity)+'</div>','<button class="btn primary" onclick="save(()=>A.updateProjectService(\''+id+'\',{name:$(\'#sn\').value,customer_price:Number($(\'#scp\').value)||0,internal_cost:Number($(\'#sic\').value)||0,quantity:Number($(\'#sq\').value)||1},\''+i.project_id+'\'),\'Service updated\')">Save</button>')}
function newQuote(pid){save(()=>A.createQuotation(pid),'Quotation created')}
function newQuoteItem(qid){const q=A.state.quotations.find(x=>x.id===qid),fs=A.state.functions.filter(f=>f.project_id===q.project_id);modal('Quotation line item','<div class="form-grid">'+field('Description','qd')+selectField('Function','qf',[['','Project level'],...fs.map(f=>[f.id,f.name])])+field('Quantity','qq','number','1')+field('Customer price / unit','qp','number')+field('Internal cost / unit','qc','number')+'</div>','<button class="btn primary" onclick="save(()=>A.addQuoteItem(\''+qid+'\',{description:$(\'#qd\').value,function_id:$(\'#qf\').value||null,quantity:Number($(\'#qq\').value)||1,customer_price:Number($(\'#qp\').value)||0,internal_cost:Number($(\'#qc\').value)||0}),\'Line item added\')">Add</button>')}
function editQuoteItem(id){const i=A.state.quotationItems.find(x=>x.id===id),q=A.state.quotations.find(x=>x.id===i.quotation_id);modal('Edit quotation line','<div class="form-grid">'+field('Description','qd','text',i.description)+field('Quantity','qq','number',i.quantity)+field('Customer price / unit','qp','number',i.customer_price)+field('Internal cost / unit','qc','number',i.internal_cost)+'</div>','<button class="btn primary" onclick="save(()=>A.updateQuoteItem(\''+id+'\',{description:$(\'#qd\').value,quantity:Number($(\'#qq\').value)||1,customer_price:Number($(\'#qp\').value)||0,internal_cost:Number($(\'#qc\').value)||0},\''+q.project_id+'\'),\'Quotation line updated\')">Save</button>')}
function updateQuoteStatus(id,status){save(()=>A.updateQuotation(id,{status}),'Quotation updated')}
function addQuoteVersion(pid,sourceId){save(async()=>{const q=await A.createQuoteVersionFrom(pid,sourceId);quoteId=q.id},'New quotation version created')}
function newDeliverable(pid){modal('Aavartan deliverable','<div class="form-grid">'+field('Deliverable','dd')+selectField('Function','df',[['','Project level'],...A.state.functions.filter(f=>f.project_id===pid).map(f=>[f.id,f.name])])+selectField('Status','ds',['pending','in_progress','completed','delivered'])+field('Due date','du','date')+'</div>','<button class="btn primary" onclick="save(()=>A.addDeliverable({project_id:\''+pid+'\',function_id:$(\'#df\').value||null,deliverable:$(\'#dd\').value,status:$(\'#ds\').value,due_date:$(\'#du\').value||null}),\'Deliverable added\')">Add</button>')}
function cycleDelivery(id,status){const n={pending:'in_progress',in_progress:'completed',completed:'delivered',delivered:'pending'}[status]||'pending';save(()=>A.updateDeliverable(id,{status:n,delivered_at:n==='delivered'?new Date().toISOString():null}),'Delivery updated')}
function newDocument(pid){modal('Project document / link','<div class="form-grid">'+field('Title','dt')+selectField('Kind','dk',['quotation','contract','drive','moodboard','venue','other'])+field('URL','du')+selectField('Status','dst',['draft','ready','sent','approved'])+'</div>','<button class="btn primary" onclick="save(()=>A.addDocument({project_id:\''+pid+'\',kind:$(\'#dk\').value,title:$(\'#dt\').value,url:$(\'#du\').value,status:$(\'#dst\').value}),\'Document saved\')">Save</button>')}
function newService(){modal('Service / package','<div class="form-grid">'+selectField('Brand','sb',['Rachna','Aavartan'])+field('Name','sn')+field('Category','sc')+field('Customer base price','sp','number')+field('Internal cost','si','number')+'</div>','<button class="btn primary" onclick="save(()=>A.addService({brand:$(\'#sb\').value,name:$(\'#sn\').value,category:$(\'#sc\').value,base_price:Number($(\'#sp\').value)||0,internal_cost:Number($(\'#si\').value)||0}),\'Service added\')">Create</button>')}
function editService(id){const s=A.state.services.find(x=>x.id===id);modal('Edit service','<div class="form-grid">'+selectField('Brand','sb',['Rachna','Aavartan'],s.brand)+field('Name','sn','text',s.name)+field('Category','sc','text',s.category||'')+field('Customer base price','sp','number',s.base_price)+field('Internal cost','si','number',s.internal_cost)+selectField('Status','sa',[['true','Active'],['false','Inactive']],String(s.active))+'</div>','<button class="btn primary" onclick="save(()=>A.addServiceOrUpdate(\''+id+'\',{brand:$(\'#sb\').value,name:$(\'#sn\').value,category:$(\'#sc\').value,base_price:Number($(\'#sp\').value)||0,internal_cost:Number($(\'#si\').value)||0,active:$(\'#sa\').value===\'true\'}),\'Service updated\')">Save</button>')}
function newMarketing(){modal('Marketing lead','<div class="form-grid">'+field('Campaign','mc')+field('Channel','mh','text','Instagram')+field('Content','mt')+field('Spend','ms','number','0')+selectField('Status','mst',['new','qualified','won','lost'])+selectField('Customer (optional)','mcu',[['','No linked customer'],...A.state.customers.map(c=>[c.id,c.name])])+'</div>','<button class="btn primary" onclick="save(()=>A.addMarketing({campaign:$(\'#mc\').value,channel:$(\'#mh\').value,content:$(\'#mt\').value,spend:Number($(\'#ms\').value)||0,lead_status:$(\'#mst\').value,customer_id:$(\'#mcu\').value||null}),\'Marketing lead saved\')">Save</button>')}
function editMarketing(id){const m=A.state.marketing.find(x=>x.id===id);modal('Edit marketing lead','<div class="form-grid">'+field('Campaign','mc','text',m.campaign||'')+field('Channel','mh','text',m.channel||'')+field('Content','mt','text',m.content||'')+field('Spend','ms','number',m.spend||0)+selectField('Status','mst',['new','qualified','won','lost'],m.lead_status)+'</div>','<button class="btn primary" onclick="save(()=>A.update(\'marketing_leads\',\''+id+'\',{campaign:$(\'#mc\').value,channel:$(\'#mh\').value,content:$(\'#mt\').value,spend:Number($(\'#ms\').value)||0,lead_status:$(\'#mst\').value}),\'Marketing lead updated\')">Save</button>')}
function authModal(){if(A.state.user){modal('Account','<p><strong>'+esc(A.state.profile?.full_name||A.state.user.email)+'</strong></p><p class="muted">'+esc(A.state.org?.name||'Workspace')+'</p>','<button class="btn primary" onclick="A.signOut().then(()=>{closeModal();render()})">Sign out</button>');return}modal('Rachna OS access','<div class="form-grid">'+field('Email','ae','email')+field('Password','ap','password')+field('Full name (new account)','afn')+field('Workspace name (new account)','aorg','text','Rachna Workspace')+'</div><p class="muted">A new account may require email confirmation before first sign-in.</p>','<button class="btn" onclick="signup()">Create account</button><button class="btn primary" onclick="signin()">Sign in</button>')}
function signin(){save(()=>A.signIn($('#ae').value,$('#ap').value),'Signed in')}
async function signup(){try{const r=await A.signUp($('#ae').value,$('#ap').value,$('#afn').value,$('#aorg').value);closeModal();render();toast(r?.needsConfirmation?'Account created. Confirm email, then sign in.':'Workspace created')}catch(e){toast(e.message,true)}}
function printWindow(title,body){const w=window.open('','_blank');if(!w){toast('Pop-up blocked by browser',true);return}w.document.write('<html><head><title>'+esc(title)+'</title><style>body{font-family:Arial,sans-serif;padding:40px;color:#222}h1,h2{font-family:Georgia,serif}table{width:100%;border-collapse:collapse;margin-top:20px}th,td{border:1px solid #ddd;padding:9px;text-align:left}.right{text-align:right}</style></head><body>'+body+'</body></html>');w.document.close();w.focus();w.print()}
function printProject(pid){const p=A.state.projects.find(x=>x.id===pid),c=A.state.customers.find(x=>x.id===p.customer_id),fs=A.state.functions.filter(f=>f.project_id===pid);printWindow(p.name,'<h1>RACHNA</h1><p>Celebrations, Composed</p><h2>'+esc(p.name)+'</h2><p>Customer: '+esc(c?.name||'')+' · Brand: '+esc(p.brand||'')+'</p><p>Quoted: '+money(p.quoted_total)+' · Advance: '+money(p.customer_advance)+' · Due: '+money(Math.max(0,Number(p.quoted_total)-Number(p.customer_advance)))+'</p><h3>Functions</h3><table><tr><th>Function</th><th>BS</th><th>AD</th><th>Venue</th><th>Guests</th></tr>'+fs.map(f=>'<tr><td>'+esc(f.name)+'</td><td>'+esc(f.event_date_bs||'')+'</td><td>'+esc(f.event_date||'')+'</td><td>'+esc(f.venue||'')+'</td><td>'+esc(f.guest_count||'')+'</td></tr>').join('')+'</table>')}
function printQuote(id){const q=A.state.quotations.find(x=>x.id===id),p=A.state.projects.find(x=>x.id===q.project_id),c=A.state.customers.find(x=>x.id===p.customer_id),items=A.state.quotationItems.filter(x=>x.quotation_id===id);printWindow('Quotation '+p.name,'<h1>RACHNA</h1><p>Celebrations, Composed</p><h2>Quotation — '+esc(p.name)+'</h2><p>Prepared for: '+esc(c?.name||'')+' · Version '+q.version+'</p><table><tr><th>Description</th><th>Function</th><th>Qty</th><th class="right">Amount</th></tr>'+items.map(i=>'<tr><td>'+esc(i.description)+'</td><td>'+esc(A.state.functions.find(f=>f.id===i.function_id)?.name||'Project')+'</td><td>'+esc(i.quantity)+'</td><td class="right">'+money(Number(i.customer_price)*Number(i.quantity))+'</td></tr>').join('')+'</table><h2 class="right">Total: '+money(q.customer_total)+'</h2><p>Booking confirmation: 30% customer advance.</p>')}
function printReport(){printWindow('Rachna Management Report','<h1>RACHNA — MANAGEMENT REPORT</h1><p>Projects: '+A.state.projects.length+' · Booked: '+A.state.projects.filter(p=>p.status==='booked').length+'</p><p>Quoted sales: '+money(A.state.projects.reduce((a,p)=>a+Number(p.quoted_total||0),0))+'</p><p>Expected gross profit: '+money(A.state.projects.reduce((a,p)=>a+Number(p.quoted_total||0)-Number(p.internal_cost||0),0))+'</p><p>Open tasks: '+A.state.tasks.filter(t=>t.status!=='done').length+'</p>')}
function backProjects(){page='projects';projectId=null;render()}function closeQuoteView(){quoteId=null;render()}function openProject(id){projectId=id;quoteId=null;projectTab='overview';render()}function openQuote(id){quoteId=id;projectId=null;render()}function editInquiryPlaceholder(){}
Object.assign(window,{render,navTo,newCustomer,editCustomer,newInquiry,openInquiry,editInquiry,updateInquiryStatus,stageNext,newProject,addFunction,editFunction,recordAdvance,save,backProjects,openProject,openQuote,closeQuoteView,newVendor,editVendor,bookVendor,payVendor,newTeam,editTeam,assignTeam,newTask,editTask,finishTask,newPayment,newExpense,newProduction,addProjectService,editProjectService,newQuote,newQuoteItem,editQuoteItem,updateQuoteStatus,addQuoteVersion,newDeliverable,cycleDelivery,newDocument,newService,editService,newMarketing,editMarketing,authModal,signin,signup,printProject,printQuote,printReport,closeModal,syncBS});
